typedef struct {
    short frame;
    short rx, ry, rz;   /* s16 binary angle, about the pivot */
    short tx, ty, tz;
} MCKey;
typedef struct {
    unsigned char bone, nkeys;
    const MCKey  *keys;
} MCTrack;
typedef struct {
    const char    *name;
    short          frames;
    unsigned char  loop, ntracks;
    const MCTrack *tracks;
} MCAnim;

